func dtNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func dtTab(b []byte, i int32, lim int32) int32 {
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func dtDec(b []byte, from int32, to int32) int32 {
	var k int32 = from
	var v int32 = 0
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	return v
}

func dtHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	return -1
}

func dtCompareHex(out *port.Cells, b []byte, from int32, to int32) int32 {
	// -1 when `out` is exactly the hex in b[from, to) (`-` is empty); -2
	// for a length difference; else the first differing index.
	var n int32 = (to - from) / 2
	var i int32 = 0
	if ((to - from) == 1) && (port.BlobU8(b, from) == 45) {
		n = 0
	}
	if port.CellsLen(out) != n {
		return -2
	}
	for i < n {
		if port.CellsAt(out, i) != ((dtHexval(port.BlobU8(b, from+(i*2))) * 16) + dtHexval(port.BlobU8(b, from+((i*2)+1)))) {
			return i
		}
		i += 1
	}
	return -1
}

func dtPts(cp int32) int32 {
	// Centipoints as whole points, rounded half up (floor of +0.5): the real
	// corpus is compared in points because poppler prints boxes with two
	// decimals, binary-rounded, and may differ from the exact decimal by a
	// centipoint (68.315 is 68.31 to poppler and 68.32 to emon).
	var x int32 = cp + 50
	var q int32 = x / 100
	if (x % 100) < 0 {
		q -= 1
	}
	return q
}

func dtDigestPts(pg *port.Cells) int32 {
	// The 23-bit rolling hash of every page's boxes in whole points and
	// its rotation.
	var n int32 = pdfdoc.PdPgCount(pg)
	var i int32 = 0
	var k int32 = 0
	var h int32 = 0
	var v int32 = 0
	for i < n {
		k = 0
		for k < 9 {
			if k < 4 {
				v = dtPts(pdfdoc.PdPgMedia(pg, i, k))
			}
			if (k >= 4) && (k < 8) {
				v = dtPts(pdfdoc.PdPgCrop(pg, i, k-4))
			}
			if k == 8 {
				v = pdfdoc.PdPgRotate(pg, i)
			}
			v = v % 8388593
			if v < 0 {
				v += 8388593
			}
			h = ((h * 131) + v) % 8388593
			k += 1
		}
		i += 1
	}
	return h
}

