func TestEveryFixtureOpensOrFailsAsNamed(emonT *testing.T) {
	// Row: file, status, pages, digest.
	var f []byte = port.TestFile("pdf/fixtures.txt")
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var status int32 = 0
	for pos < n {
		line += 1
		e = dtNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = dtTab(f, pos, e)
			s1 = dtTab(f, s0+1, e)
			s2 = dtTab(f, s1+1, e)
			var t *strings.Builder = port.NewText()
			status = dtRunFixturesRow(f, pos, s0, ar, dc, a, b, st, pg, t)
			port.AssertTextSpan(emonT, t, f, s0+1, s1, "status", line)
			if status == 0 {
				port.AssertEqAt(emonT, pdfdoc.PdPgCount(pg), dtDec(f, s1+1, s2), "page count", line)
				port.AssertEqAt(emonT, dtDigest(pg), dtDec(f, s2+1, e), "page boxes and rotation", line)
			}
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows > 20, "the fixtures were read")
}

func dtObjectRow(names []byte, from int32, to int32, num int32, kind int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, out *port.Cells, t *strings.Builder) int32 {
	// Open the file, then: kind 111 (o) dumps object num into t (`!missing`
	// when there is none); kind 115 (s) decodes it into `out` and writes the
	// status name to t. Answers the pd-open status (non-zero: not opened).
	var pdf []byte = port.TestFileSpan(names, from, to)
	var status int32 = pdfdoc.PdOpen(pdf, ar, dc, a, b, st)
	var h int32 = 0
	var s int32 = 0
	if status != 0 {
		return status
	}
	h = pdfdoc.PdGet(pdf, ar, dc, a, b, st, num)
	if kind == 111 {
		if h == 0 {
			port.TextAscii(t, "!missing")
		} else {
			pdflex.PlDump(t, ar, h)
		}
	}
	if kind == 115 {
		port.CellsDrop(out, 0)
		if h == 0 {
			port.TextAscii(t, "!missing")
		} else {
			s = pdfdoc.PdStreamData(pdf, ar, dc, a, b, st, h, out)
			pdffilter.PfStatusEmitName(t, s)
		}
	}
	return 0
}

